export type YieldDto = {
    /** Unique identifier for this yield opportunity */
    id: string;
    /** Network this yield opportunity is on */
    network: YieldDtoNetwork;
    /** EVM chain ID for this network (only for EVM networks) */
    chainId?: string;
    /** Accepted input tokens (auto-converted as needed) */
    inputTokens: TokenDto[];
    /** Token received from the protocol */
    outputToken?: TokenDto;
    /** Canonical deposit token - used for balances */
    token: TokenDto;
    /** Canonical deposit tokens - used for balances */
    tokens: TokenDto[];
    /** Total effective yield broken down by source and token. */
    rewardRate: RewardRateDto;
    /** Key statistics and analytics for this yield opportunity */
    statistics?: YieldStatisticsDto;
    /** Risk scores and provider ratings for this yield */
    risk?: YieldRiskDto;
    /** Current availability of user actions like enter, exit, claim */
    status: YieldStatusDto;
    /** Descriptive metadata including name, logo, description, and documentation */
    metadata: YieldMetadataDto;
    /** Operational mechanics including constraints, fees, and capabilities */
    mechanics: YieldMechanicsDto;
    /** The provider ID this yield belongs to */
    providerId: string;
    /** Curator information for the yield (if applicable) */
    curator?: CuratorDto;
    /** Optional tags for filtering or categorization */
    tags?: string[];
    /** Dynamic, real-time protocol-level state values that affect entering or exiting a yield (e.g., pool price, capacity, price per share, liquidity, queue depth) */
    state?: YieldStateDto;
};

/**
 * Type of balance
 */
export type BalanceType = (typeof BalanceType)[keyof typeof BalanceType];

export const BalanceType = {
    active: 'active',
    entering: 'entering',
    exiting: 'exiting',
    withdrawable: 'withdrawable',
    claimable: 'claimable',
    locked: 'locked',
} as const;

/**
 * High-level action intent
 */
export type PendingActionDtoIntent =
    (typeof PendingActionDtoIntent)[keyof typeof PendingActionDtoIntent];

export const PendingActionDtoIntent = {
    enter: 'enter',
    manage: 'manage',
    exit: 'exit',
} as const;

/**
 * Specific action type
 */
export type PendingActionDtoType = (typeof PendingActionDtoType)[keyof typeof PendingActionDtoType];

export const PendingActionDtoType = {
    STAKE: 'STAKE',
    UNSTAKE: 'UNSTAKE',
    CLAIM_REWARDS: 'CLAIM_REWARDS',
    AUTO_SWEEP_UNSTAKE_REWARDS: 'AUTO_SWEEP_UNSTAKE_REWARDS',
    AUTO_SWEEP_WITHDRAW_REWARDS: 'AUTO_SWEEP_WITHDRAW_REWARDS',
    RESTAKE_REWARDS: 'RESTAKE_REWARDS',
    WITHDRAW: 'WITHDRAW',
    WITHDRAW_ALL: 'WITHDRAW_ALL',
    RESTAKE: 'RESTAKE',
    CLAIM_UNSTAKED: 'CLAIM_UNSTAKED',
    UNLOCK_LOCKED: 'UNLOCK_LOCKED',
    STAKE_LOCKED: 'STAKE_LOCKED',
    VOTE: 'VOTE',
    REVOKE: 'REVOKE',
    VOTE_LOCKED: 'VOTE_LOCKED',
    REVOTE: 'REVOTE',
    REBOND: 'REBOND',
    MIGRATE: 'MIGRATE',
    VERIFY_WITHDRAW_CREDENTIALS: 'VERIFY_WITHDRAW_CREDENTIALS',
    DELEGATE: 'DELEGATE',
} as const;

export type PendingActionDto = {
    /** High-level action intent */
    intent: PendingActionDtoIntent;
    /** Specific action type */
    type: PendingActionDtoType;
    /** Server-generated passthrough that must be included when executing the action */
    passthrough: string;
    /** Argument schema required to execute this action */
    arguments?: ArgumentSchemaDto | null;
    /**
     * Amount involved in the action, in human-readable token units (not the smallest denomination).
     * @nullable
     */
    amount?: string | null;
};

export type RevShareDetailsDto = {
    /** Minimum revenue share percentage (0-1) */
    minRevShare: number;
    /** Maximum revenue share percentage (0-1) */
    maxRevShare: number;
};

export type RevShareTiersDto = {
    /** Trial tier revenue share details */
    trial?: RevShareDetailsDto;
    /** Standard tier revenue share details */
    standard?: RevShareDetailsDto;
    /** Pro tier revenue share details */
    pro?: RevShareDetailsDto;
};

/**
 * Total TVL across the entire provider in USD
 * @nullable
 */
export type ValidatorProviderDtoTvlUsd = { [key: string]: unknown } | null;

/**
 * Type of provider (protocol or validator provider)
 */
export type ValidatorProviderDtoType =
    (typeof ValidatorProviderDtoType)[keyof typeof ValidatorProviderDtoType];

export const ValidatorProviderDtoType = {
    protocol: 'protocol',
    validator_provider: 'validator_provider',
} as const;

export type ValidatorProviderDto = {
    /** Provider name */
    name: string;
    /** Provider ID */
    id: string;
    /** Provider logo URI */
    logoURI: string;
    /** Short description of the provider */
    description: string;
    /** Provider website */
    website: string;
    /**
     * Total TVL across the entire provider in USD
     * @nullable
     */
    tvlUsd: ValidatorProviderDtoTvlUsd;
    /** Type of provider (protocol or validator provider) */
    type: ValidatorProviderDtoType;
    /**
     * Optional social/media references or audit links
     * @nullable
     */
    references?: string[] | null;
    /** Provider ranking (lower numbers indicate higher preference) */
    rank: number;
    /** Whether this provider is marked as preferred */
    preferred: boolean;
    /** Revenue sharing details by tier */
    revshare?: RevShareTiersDto;
    /**
     * Provider ID (deprecated, use `id` instead)
     * @deprecated
     */
    uniqueId?: string;
    /**
     * Creation timestamp (deprecated)
     * @deprecated
     */
    createdAt?: string;
    /**
     * Last update timestamp (deprecated)
     * @deprecated
     */
    updatedAt?: string;
};

export type ValidatorDto = {
    /** Validator address or ID */
    address: string;
    /** Validator display name */
    name?: string;
    /** Validator logo URI */
    logoURI?: string;
    /** Link to validator website */
    website?: string;
    /** Detailed reward rate breakdown by source (emissions, MEV, fees, etc.) */
    rewardRate?: RewardRateDto;
    /** Provider information for this validator */
    provider?: ValidatorProviderDto;
    /** Commission rate charged by validator */
    commission?: number;
    /** Total value locked with this validator in USD */
    tvlUsd?: string;
    /** Total value locked with this validator in native token */
    tvl?: string;
    /** Raw total value locked with this validator (full precision) */
    tvlRaw?: string;
    /** Validator's voting power share (0–1) */
    votingPower?: number;
    /** Whether this validator is flagged as preferred */
    preferred?: boolean;
    /** Minimum stake allowed in native token */
    minimumStake?: string;
    /** Maximum available stake before hitting cap in native token */
    remainingPossibleStake?: string;
    /** Number of remaining nominator/delegator slots (for capped chains) */
    remainingSlots?: number;
    /** Number of current nominators */
    nominatorCount?: number;
    /** Validator status description (active, jailed, unbonding, etc.) */
    status?: string;
    /** ID of the provider backing this validator */
    providerId?: string;
    /** Price per share of the validator */
    pricePerShare?: string;
    /** Subnet ID */
    subnetId?: number;
    /** Subnet name */
    subnetName?: string;
    /** Market cap of the subnet */
    marketCap?: string;
    /** Token symbol of the subnet */
    tokenSymbol?: string;
};

/**
 * Price range for concentrated liquidity positions in tokens[1]/tokens[0] format (e.g., if tokens[0]=WETH and tokens[1]=USDC, then priceRange represents USDC/WETH)
 */
export type BalanceDtoPriceRange = { [key: string]: unknown };

export type BalanceDto = {
    /** User wallet address that owns this balance */
    address: string;
    type: BalanceType;
    /** Balance amount in underlying token */
    amount: string;
    /** Raw balance amount (full precision) */
    amountRaw: string;
    /**
     * Date relevant to this balance state
     * @nullable
     */
    date?: string | null;
    /** Fee configuration ID (if applicable) */
    feeConfigurationId?: string;
    /** Pending actions for this balance */
    pendingActions: PendingActionDto[];
    /** Token used for balance amounts */
    token: TokenDto;
    /** Validator information (if applicable) */
    validator?: ValidatorDto | null;
    /**
     * Multiple validators information (when balance is distributed across multiple validators)
     * @nullable
     */
    validators?: ValidatorDto[] | null;
    /**
     * Value of the balance in USD
     * @nullable
     */
    amountUsd?: string | null;
    /** Whether this balance is currently earning rewards */
    isEarning: boolean;
    /** Price range for concentrated liquidity positions in tokens[1]/tokens[0] format (e.g., if tokens[0]=WETH and tokens[1]=USDC, then priceRange represents USDC/WETH) */
    priceRange?: BalanceDtoPriceRange;
    /** NFT token ID for liquidity positions (e.g., PancakeSwap V3 position NFT ID) */
    tokenId?: string;
    /** Share balance in human-readable format */
    shareAmount?: string;
    /** Share balance in full precision (smallest unit) */
    shareAmountRaw?: string;
    /** The share token that shareAmount and shareAmountRaw are denominated in */
    shareToken?: TokenDto;
};

export type YieldBalancesDto = {
    /** Unique identifier of the yield */
    yieldId: string;
    /** List of balances for this yield */
    balances: BalanceDto[];
    /** Balance for the output token */
    outputTokenBalance?: BalanceDto | null;
    /** Personalized reward rate breakdown for this balance position */
    rewardRate?: RewardRateDto | null;
};

export type YieldErrorDto = {
    /** Unique identifier of the yield that failed */
    yieldId: string;
    /** Error message describing what went wrong */
    error: string;
};

export type BalancesResponseDto = {
    /** Successful yield balance results */
    items: YieldBalancesDto[];
    /** Errors encountered while fetching balances */
    errors: YieldErrorDto[];
};

